1: import type {MarketAsset, MarketSnapshot} from '../models/market';
2: import {getMarketRecommendation} from './recommendation';
3: 
4: export const MARKET_DATA_SOURCE = {
5:   name: 'CoinGecko',
6:   url: 'https://www.coingecko.com/',
7: } as const;
8: 
9: export const MARKET_DISCLAIMER =
10:   'Информация носит справочный характер и не является индивидуальной инвестиционной рекомендацией. Криптоактивы волатильны, а прошлое движение цены не гарантирует будущий результат.';
11: 
12: export const MARKET_ASSET_IDS = [
13:   'bitcoin',
14:   'ethereum',
15:   'solana',
16:   'binancecoin',
17:   'ripple',
18: ] as const;
19: 
20: const COINGECKO_MARKETS_ENDPOINT =
21:   'https://api.coingecko.com/api/v3/coins/markets';
22: 
23: export interface MarketFetchResponse {
24:   ok: boolean;
25:   status: number;
26:   json(): Promise<unknown>;
27: }
28: 
29: export type MarketFetch = (url: string) => Promise<MarketFetchResponse>;
30: 
31: interface CoinGeckoMarketRow {
32:   id: string;
33:   symbol: string;
34:   name: string;
35:   current_price: number;
36:   price_change_percentage_24h: number | null;
37:   last_updated: string | null;
38: }
