40: export class MarketServiceError extends Error {
41:   readonly status: number | null;
42: 
43:   constructor(message: string, status: number | null = null) {
44:     super(message);
45:     this.name = 'MarketServiceError';
46:     this.status = status;
47:   }
48: }
49: 
50: export async function fetchMarketSnapshot(
51:   fetchImpl: MarketFetch = defaultMarketFetch,
52: ): Promise<MarketSnapshot> {
53:   const url = buildMarketsUrl();
54:   let response: MarketFetchResponse;
55: 
56:   try {
57:     response = await fetchImpl(url);
58:   } catch (error) {
59:     throw new MarketServiceError(
60:       `Не удалось получить рыночные данные: ${toErrorMessage(error)}`,
61:     );
62:   }
63: 
64:   if (!response.ok) {
65:     throw new MarketServiceError(
66:       `Рыночный API вернул ошибку HTTP ${response.status}.`,
67:       response.status,
68:     );
69:   }
70: 
71:   let payload: unknown;
72:   try {
73:     payload = await response.json();
74:   } catch (error) {
75:     throw new MarketServiceError(
76:       `Не удалось прочитать ответ рыночного API: ${toErrorMessage(error)}`,
77:       response.status,
78:     );
79:   }
80: 
81:   const rows = parseMarketRows(payload);
82:   const assets = rows.map(toMarketAsset);
83:   const bitcoin = assets.find(asset => asset.id === 'bitcoin');
84: 
85:   if (!bitcoin) {
86:     throw new MarketServiceError('В ответе рыночного API отсутствует курс Bitcoin.');
87:   }
88: 
89:   return {
90:     bitcoinUsd: bitcoin.currentPriceUsd,
91:     assets,
92:     fetchedAt: new Date().toISOString(),
93:     source: MARKET_DATA_SOURCE,
94:     disclaimer: MARKET_DISCLAIMER,
95:   };
96: }
97: 
98: export function buildMarketsUrl(): string {
99:   const params = new URLSearchParams({
100:     vs_currency: 'usd',
101:     ids: MARKET_ASSET_IDS.join(','),
102:     order: 'market_cap_desc',
103:     sparkline: 'false',
104:     price_change_percentage: '24h',
105:   });
106: 
107:   return `${COINGECKO_MARKETS_ENDPOINT}?${params.toString()}`;
108: }
109: 
110: async function defaultMarketFetch(url: string): Promise<MarketFetchResponse> {
111:   return fetch(url);
112: }
113: 
114: function parseMarketRows(payload: unknown): CoinGeckoMarketRow[] {
115:   if (!Array.isArray(payload)) {
116:     throw new MarketServiceError('Рыночный API вернул данные в неожиданном формате.');
117:   }
118: 
119:   return payload.map((row, index) => {
120:     if (!isRecord(row)) {
121:       throw new MarketServiceError(`Некорректная запись актива с индексом ${index}.`);
122:     }
123: 
124:     const id = readString(row.id);
125:     const symbol = readString(row.symbol);
126:     const name = readString(row.name);
127:     const currentPrice = readFiniteNumber(row.current_price);
128:     const priceChange = readNullableFiniteNumber(row.price_change_percentage_24h);
129:     const lastUpdated = readNullableString(row.last_updated);
130: 
131:     if (!id || !symbol || !name || currentPrice === null) {
132:       throw new MarketServiceError(`Неполные данные актива с индексом ${index}.`);
133:     }
134: 
135:     return {
136:       id,
137:       symbol,
138:       name,
139:       current_price: currentPrice,
140:       price_change_percentage_24h: priceChange,
141:       last_updated: lastUpdated,
142:     };
143:   });
144: }
145: 
146: function toMarketAsset(row: CoinGeckoMarketRow): MarketAsset {
147:   return {
148:     id: row.id,
149:     symbol: row.symbol.toUpperCase(),
150:     name: row.name,
151:     currentPriceUsd: row.current_price,
152:     priceChange24hPercent: row.price_change_percentage_24h,
153:     lastUpdated: row.last_updated,
154:     recommendation: getMarketRecommendation(row.price_change_percentage_24h),
155:   };
156: }
157: 
158: function isRecord(value: unknown): value is Record<string, unknown> {
159:   return typeof value === 'object' && value !== null;
160: }
161: 
162: function readString(value: unknown): string | null {
163:   return typeof value === 'string' && value.length > 0 ? value : null;
164: }
165: 
166: function readNullableString(value: unknown): string | null {
167:   return value === null || value === undefined ? null : readString(value);
168: }
169: 
170: function readFiniteNumber(value: unknown): number | null {
171:   return typeof value === 'number' && Number.isFinite(value) ? value : null;
172: }
173: 
174: function readNullableFiniteNumber(value: unknown): number | null {
175:   return value === null || value === undefined ? null : readFiniteNumber(value);
176: }
177: 
178: function toErrorMessage(error: unknown): string {
179:   return error instanceof Error ? error.message : 'неизвестная ошибка';
180: }
