1: import type {MarketRecommendation} from '../models/market';
2: 
3: const HIGH_RISK_ABSOLUTE_CHANGE_PERCENT = 7;
4: const WATCH_POSITIVE_CHANGE_PERCENT = 2;
5: 
6: /**
7:  * Produces an informational label from 24h price movement only.
8:  * It intentionally does not attempt to predict future returns or tell a user what to buy.
9:  */
10: export function getMarketRecommendation(
11:   priceChange24hPercent: number | null,
12: ): MarketRecommendation {
13:   if (priceChange24hPercent === null || !Number.isFinite(priceChange24hPercent)) {
14:     return {
15:       kind: 'neutral',
16:       label: 'Нейтрально',
17:       reason: 'Недостаточно данных о движении цены за последние 24 часа.',
18:     };
19:   }
20: 
21:   const absoluteChange = Math.abs(priceChange24hPercent);
22: 
23:   if (absoluteChange >= HIGH_RISK_ABSOLUTE_CHANGE_PERCENT) {
24:     return {
25:       kind: 'high_risk',
26:       label: 'Повышенный риск',
27:       reason: `Цена изменилась на ${formatPercent(priceChange24hPercent)} за 24 часа; высокая краткосрочная волатильность требует осторожности.`,
28:     };
29:   }
30: 
31:   if (priceChange24hPercent >= WATCH_POSITIVE_CHANGE_PERCENT) {
32:     return {
33:       kind: 'watch',
34:       label: 'Интересно наблюдать',
35:       reason: `Цена выросла на ${formatPercent(priceChange24hPercent)} за 24 часа; это сигнал движения, а не прогноз дальнейшего роста.`,
36:     };
37:   }
38: 
39:   return {
40:     kind: 'neutral',
41:     label: 'Нейтрально',
42:     reason: `Изменение за 24 часа (${formatPercent(priceChange24hPercent)}) не превышает заданные пороги наблюдения и риска.`,
43:   };
44: }
45: 
46: function formatPercent(value: number): string {
47:   const sign = value > 0 ? '+' : '';
48:   return `${sign}${value.toFixed(2)}%`;
49: }
